picture_charsheet_v2.script:
-- The frame shows the full-size picture: the record's "portrait" field
-- (FGU saves the chosen picture there) instead of the small character
-- list copy. A book pregen falls back to its token. Follows changes.
local _sPortraitPath = nil;
function createBaseWidget()
	super.createBaseWidget();
	local node = window.getDatabaseNode();
	if node and not _sPortraitPath then
		_sPortraitPath = DB.getPath(node, "portrait");
		DB.addHandler(_sPortraitPath, "onUpdate", applyFullPortrait);
	end
	applyFullPortrait();
end
function applyFullPortrait()
	local node = window.getDatabaseNode();
	local w = findWidget("portrait");
	if not node or not w then return; end
	local bChar = DB.getPath(node):match("^charsheet%.") ~= nil;
	local sAsset = DB.getValue(node, "portrait", "");
	if not Interface.isToken(sAsset) and not bChar then
		sAsset = DB.getValue(node, "token", "");
	end
	-- A picture this computer cannot load (a player's own portrait pack
	-- on another machine) keeps FGU's uploaded copy instead.
	if Interface.isToken(sAsset) then
		w.setAsset(sAsset);
	elseif bChar then
		w.setBitmap(string.format("portrait_%s_charlist", DB.getName(node)));
	end
end
function onClose()
	if _sPortraitPath then DB.removeHandler(_sPortraitPath, "onUpdate", applyFullPortrait); end
	if super and super.onClose then super.onClose(); end
end
